/* Know Your Candidate - one state's page, and the directory of states.
 *
 * The page is generated by kyc/pages.py with nothing in it but the state
 * code; everything a reader sees is rendered here from the same profiles.js
 * the grid and the map load, so a state page can never disagree with them
 * about who represents a district. Which page this is comes from
 * <body data-page="state" data-state="TX"> or <body data-page="states">.
 */
(function (global) {
  "use strict";

  var doc = global.document;
  var KYC = global.KYC;
  var data = global.legislatorsData || [];
  var races = global.kycRaces || [];
  var cards = KYC.cards;

  var code = doc.body.getAttribute("data-state") || "";
  var kind = doc.body.getAttribute("data-page") || "state";

  function el(id) {
    return doc.getElementById(id);
  }

  function plural(n, word, words) {
    return n + " " + (n === 1 ? word : (words || word + "s"));
  }

  /* ------------------------------------------------------------ one state */

  function peopleIn(race) {
    return race.incumbentIds.concat(race.candidateIds).map(KYC.byId).filter(Boolean);
  }

  function districtLabel(race) {
    if (race.chamber === "Senate") return "U.S. Senate";
    if (!race.district) return "At-large seat";
    return "District " + race.district;
  }

  /* How to vote here: the state's own pages, as the secretaries of state's
   * association lists them (kyc/voting.py). Nothing on the site said how,
   * when or where to vote. No date is typed here: the dates are the
   * jurisdiction's own, from the pipeline (kyc/voting_dates.py, datesFor).
   * NASS covers the 50 states and D.C.; a territory's links are its own
   * office's (voting.TERRITORY_LINKS). */
  var VOTING = [
    ["status", "Check your registration"],
    ["polling", "Find your polling place"],
    ["sample", "See a sample ballot"],
    ["absentee", "Vote absentee or early"],
    // Before the form, so the deadline is reached first (PR #94 review).
    // Only where the jurisdiction's own record does not say when its
    // registration closes (voting.for_page): a compiled table beside the
    // state's own dates is a second source that may disagree (rule 53).
    ["deadlines", "Registration deadlines (vote.gov)"],
    ["register", "Register to vote"],
    ["info", "Election information"],
    ["results", "Official results"],
  ];
  // A place's own name where its short name is not one (rule 75).
  var PLACE = {
    DC: "the District of Columbia",
    MP: "the Northern Mariana Islands",
    VI: "the U.S. Virgin Islands",
  };

  // One possessive for every page, as kyc/pages.py writes it (rules 12 and
  // 75): "Virgin Islands'", "Texas's" - this file's own copy wrote "Texas'".
  var possessive = KYC.possessive;

  /** "“A”, “B” and “C”": the links of *kinds*, by the words on them. */
  function quoted(kinds, labels) {
    var words = VOTING.filter(function (v) { return kinds.indexOf(v[0]) !== -1; })
      .map(function (v) { return "“" + KYC.escapeHtml(labels[v[0]] || v[1]) + "”"; });
    return words.length < 2 ? words.join("")
      : words.slice(0, -1).join(", ") + " and " + words[words.length - 1];
  }

  /** Today's date as "YYYY-MM-DD", on the reader's clock. */
  function isoToday() {
    var now = new Date();
    return now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" +
      ("0" + now.getDate()).slice(-2);
  }
  var MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July",
                     "August", "September", "October", "November", "December"];

  function longDate(iso) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ""));
    return m ? MONTH_NAMES[+m[2] - 1] + " " + (+m[3]) + ", " + m[1] : "";
  }

  function outLink(href, text) {
    return '<a href="' + KYC.escapeAttr(href) + '" target="_blank" rel="noopener noreferrer">' +
      KYC.escapeHtml(text) + "</a>";
  }

  var SHORT_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct",
                      "Nov", "Dec"];

  function shortDate(iso) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ""));
    return m ? SHORT_MONTHS[+m[2] - 1] + " " + (+m[3]) : "";
  }

  /* The jurisdiction's own dates (kyc/voting_dates.py), as its election
   * office gives them, each line linked to the page that says it. Seventeen
   * days out the page offered "Register to vote" in Georgia twelve days
   * after its deadline and gave no early-voting or mail-ballot date
   * (audit 2026-10-17, STATEGOV-11, PERSONA-03, FRESHNESS-11). Which dates
   * are words and which a reader's calendar day has passed is the only
   * thing decided here, on the reader's own clock, as KYC.electionStatus
   * counts days. From the day after the election, only what still matters
   * stays: a mailed ballot that may still arrive, a runoff. Once a date has
   * passed, a line says what the date was, never what will happen on it
   * (rule 63). */
  function datesFor(all, code) {
    var dates = all._dates || {};
    var mine = (dates.states || {})[code];
    if (!mine) return null;
    var today = isoToday();
    var election = dates.election || "2026-11-03";
    var after = today > election;
    var lines = (mine.lines || []).filter(function (l) {
      if (!after) return true;
      if (!l.keep) return false;
      // A ballot that can no longer arrive is no longer news; a runoff's
      // date is said in the past tense once it has gone.
      return l.k === "runoff" || !(l.d < today);
    });
    return { mine: mine, lines: lines, today: today, election: election, after: after };
  }

  /** Where a line's date stands on the reader's calendar. */
  function when(line, today) {
    if (!line.d) return null;
    if (line.e) {
      if (today > line.e) return { cls: "is-past", word: "Ended" };
      if (today >= line.d) return { cls: "is-now", word: "Under way" };
      return null;
    }
    if (today > line.d) return { cls: "is-past", word: "Passed" };
    if (today === line.d) return { cls: "is-now", word: "Today" };
    return null;
  }

  function lineSources(mine, line) {
    var links = (line.src || []).map(function (i) {
      return mine.urls[i] ? outLink(mine.urls[i], mine.labels[i] || mine.urls[i]) : "";
    }).filter(Boolean);
    // Semicolons between sources: an archived page's label carries its own
    // date in brackets, and commas ran one label into the next.
    return links.length ? ' <span class="vote-src">(' + links.join("; ") + ")</span>" : "";
  }

  /* The sentence a reader came for: can I still register for November 3?
   * Said only until Election Day, and only from the record's own dates.
   * Where a reader can register and vote at once, a deadline before
   * Election Day is the regular one, never "the last day" and never
   * "open until": Illinois's page told readers on October 18 that it was
   * the last day to register, with grace-period registration running to
   * November 3 (PR #102 review). Where the record does not say whether
   * there is same-day registration, the deadline is said and nothing
   * more. */
  function registrationLead(info, place) {
    var reg = info.mine.register;
    if (!reg || info.after || !reg.by) return "";
    var day = longDate(reg.by);
    var t = info.today;
    var how = " (" + reg.how + ")";
    var text;
    if (reg.sameDay) {
      var until = reg.through ? ", until " + longDate(reg.through) : "";
      var then = "you can still register and vote at the same time" + until +
        "; where and when " + place + " offers it is below.";
      if (reg.by >= info.election) {
        text = t < reg.by ? "You can still register for November 3, through Election Day" + how + "."
          : "Today, Election Day, you can still register" + how + ".";
      } else if (reg.through && t > reg.through) {
        text = "The regular deadline to register for November 3 was " + day +
          ", and same-day registration ended on " + longDate(reg.through) + ".";
      } else if (t < reg.by) {
        text = "The regular deadline to register for November 3 is " + day + how + "; after it " + then;
      } else if (t === reg.by) {
        text = "Today is the regular deadline to register for November 3" + how + "; after it " + then;
      } else {
        text = "The regular deadline to register for November 3 was " + day + "; " + then;
      }
    } else if (reg.sameDay === false) {
      text = t < reg.by ? "Registration for November 3 is open until " + day + how + "."
        : t === reg.by ? "Today is the last day to register for November 3" + how + "."
        : "Registration for November 3 closed on " + day + ".";
    } else {
      text = t < reg.by ? "The deadline to register for November 3 is " + day + how + "."
        : t === reg.by ? "Today is the deadline to register for November 3" + how + "."
        : "The deadline to register for November 3 was " + day + ".";
    }
    return '<p class="vote-lead">' + KYC.escapeHtml(text) + "</p>";
  }

  /* What the "Register to vote" button adds once registration for
   * November 3 has closed, or "" while it is open. Only where the record
   * says there is no same-day route, or that the route has ended: New
   * York's record says neither, and its lead only gives the deadline. */
  function registrationClosed(info) {
    var reg = info && info.mine.register;
    if (!reg || !reg.by || info.after) return "";
    if (reg.sameDay === false && info.today > reg.by) return "closed for Nov 3 on " + shortDate(reg.by);
    if (reg.sameDay && reg.through && info.today > reg.through) {
      return "same-day registration ended " + shortDate(reg.through);
    }
    return "";
  }

  /** A button's label with a note: "Registration package (PDF; closed ...)". */
  function withNote(label, note) {
    if (!note) return label;
    return /\)$/.test(label) ? label.slice(0, -1) + "; " + note + ")" : label + " (" + note + ")";
  }

  /* VISUALS-25: the dates as a strip, in order, Election Day among them and
   * a mark for today. Page text, never SVG text (rule 46); it wraps on a
   * phone rather than scrolling the page sideways. */
  function calendarStrip(info) {
    var items = info.lines.filter(function (l) { return l.d; }).map(function (l) {
      return { d: l.d, e: l.e, s: l.s, sp: l.sp, line: l };
    });
    if (!items.length) return "";
    items.push({ d: info.election, s: "Election Day", election: true });
    items.sort(function (a, b) { return a.d < b.d ? -1 : a.d > b.d ? 1 : 0; });
    var html = [];
    var marked = false;
    // Today has a mark of its own wherever it falls, first included (the
    // strip of a state whose first date was tomorrow had none), unless a
    // date of the strip is today itself.
    var onToday = items.some(function (item) { return item.d === info.today && !item.e; });
    function today() {
      marked = true;
      html.push('<li class="vote-cal-item is-today" aria-label="Today, ' +
        KYC.escapeAttr(longDate(info.today)) + '"><span class="vote-cal-date">' +
        KYC.escapeHtml(shortDate(info.today)) + '</span><span class="vote-cal-label">Today</span></li>');
    }
    items.forEach(function (item) {
      var end = item.e || item.d;
      if (!marked && !onToday && info.today < item.d) today();
      var past = end < info.today;
      var cls = past ? " is-past"
        : (item.d <= info.today && info.today <= end ? " is-now" : "");
      var date = shortDate(item.d) + (item.e ? "–" + shortDate(item.e).replace(
        shortDate(item.d).split(" ")[0] + " ", "") : "");
      // A date gone is named for what it was ("Runoff date"), never what
      // may still happen on it ("Runoff, if needed").
      var label = past && item.sp ? item.sp : item.s;
      html.push('<li class="vote-cal-item' + cls + (item.election ? " is-election" : "") + '">' +
        '<span class="vote-cal-date">' + KYC.escapeHtml(date) + "</span>" +
        '<span class="vote-cal-label">' + KYC.escapeHtml(label || "") + "</span></li>");
    });
    if (!marked && !onToday) today();
    return '<ol class="vote-cal" aria-label="Key dates, in order">' + html.join("") + "</ol>";
  }

  function keyDates(info) {
    if (!info || !info.lines.length) return "";
    var today = info.today;
    return '<ul class="vote-dates">' + info.lines.map(function (l) {
      var status = when(l, today);
      var past = l.d && (l.e || l.d) < today;
      var words = past && l.p ? l.p : l.t;
      var date = l.d ? (l.e ? longDate(l.d).replace(/, \d{4}$/, "") + " – " + longDate(l.e)
                            : longDate(l.d)) : "";
      return '<li data-kind="' + KYC.escapeAttr(l.k) + '">' +
        (date ? "<strong>" + KYC.escapeHtml(date) + ".</strong> " : "") +
        KYC.escapeHtml(words) + "." +
        (status && !(past && l.p) ? ' <span class="vote-when ' + status.cls + '">' +
          KYC.escapeHtml(status.word) + "</span>" : "") +
        lineSources(info.mine, l) + "</li>";
    }).join("") + "</ul>";
  }

  /** Where the block's links come from, said link by link from the
   *  pipeline's record of each (voting.effective): "the first four from
   *  NASS" credited NASS with eleven states' sample-ballot pages, Wyoming's
   *  results page and D.C.'s mail-ballot page (PR #94 review). And
   *  "each link opened" is said only when every link was found live. */
  function votingSources(all, code, links, labels, place) {
    var shown = VOTING.map(function (v) { return v[0]; }).filter(function (k) { return links[k]; });
    var nass = ((all._nass || {})[code] || []).filter(function (k) { return links[k]; });
    var own = shown.filter(function (k) { return nass.indexOf(k) === -1 && k !== "deadlines"; });
    var office = (all._territories || {})[code];
    var out = [];
    if (nass.length) {
      out.push(quoted(nass, labels) + (nass.length === 1 ? " is " : " are ") +
        KYC.escapeHtml(possessive(place)) + " own official page" + (nass.length === 1 ? "" : "s") +
        " as the National Association of Secretaries of State’s " +
        outLink(all._source || "https://www.nass.org/can-I-vote", "Can I Vote") +
        (all._listed ? " listed " + (nass.length === 1 ? "it" : "them") + " on " +
          KYC.escapeHtml(all._listed) : " lists " + (nass.length === 1 ? "it" : "them")) + ".");
    }
    if (own.length) {
      out.push(quoted(own, labels) + (own.length === 1 ? " is " : " are ") +
        (office ? "the " + outLink(office.url, office.name) + (/s$/.test(office.name) ? "'" : "'s") +
          " own page" + (own.length === 1 ? "" : "s") +
          "; the National Association of Secretaries of State lists no territory."
        : KYC.escapeHtml(possessive(place)) + " election office's own page" +
          (own.length === 1 ? "" : "s") + ", as its site links " + (own.length === 1 ? "it." : "them.")));
    }
    if (links.deadlines) {
      // The deadlines are vote.gov's to state, never typed here, and the
      // page never calls one passed (STATEGOV-11, PERSONA-03).
      out.push("“" + KYC.escapeHtml(labels.deadlines || "Registration deadlines (vote.gov)") +
        "” is the page for " + KYC.escapeHtml(place) + " on vote.gov, the federal government's " +
        "voting site, which gives the registration rules there, deadlines included.");
    }
    if (all._opened) {
      // A link refused or unanswered concludes nothing (rule 8): said as
      // unconfirmed, never as broken, and never counted as opened.
      var missed = ((all._unreached || {})[code] || []).filter(function (k) { return links[k]; });
      out.push(missed.length
        ? "Links checked " + KYC.escapeHtml(all._opened) + "; " + quoted(missed, labels) +
          " could not be confirmed by this site's automated check that day."
        : "Each link opened " + KYC.escapeHtml(all._opened) + ".");
    }
    return out.join(" ");
  }

  function votingBlock(code, name) {
    var all = KYC.meta().voting || {};
    var links = all[code];
    if (!links) return "";
    // A per-state label where NASS's kind does not fit the state: North
    // Dakota does not register voters (overrides.VOTING_LINKS); a
    // territory's office words its own pages (voting.TERRITORY_LINKS).
    var labels = (all._labels || {})[code] || {};
    var place = PLACE[code] || name;
    var info = datesFor(all, code);
    var closed = registrationClosed(info);
    return '<section class="state-section vote-box" id="voting" aria-labelledby="votingHead">' +
      '<h2 class="state-heading" id="votingHead">' + KYC.icon("vote") + " Voting in " +
        KYC.escapeHtml(place) + "</h2>" +
      (info ? registrationLead(info, place) + calendarStrip(info) : "") +
      '<p class="state-links">' + VOTING.filter(function (v) { return links[v[0]]; }).map(function (v) {
        var label = labels[v[0]] || v[1];
        // Never offered as open once it has closed (STATEGOV-11): the
        // form still registers a reader for later elections.
        if (v[0] === "register") label = withNote(label, closed);
        return '<a class="btn" target="_blank" rel="noopener noreferrer" href="' +
          KYC.escapeAttr(links[v[0]]) + '" data-kind="' + KYC.escapeAttr(v[0]) + '"' +
          (v[0] === "register" && closed ? ' data-closed="true"' : "") + ">" +
          KYC.icon("link") + " " + KYC.escapeHtml(label) + "</a>";
      }).join(" ") + "</p>" +
      keyDates(info) +
      '<p class="state-note">' + datesNote(all, info) + votingSources(all, code, links, labels, place) +
        " Hours and ID rules are on the election office's pages.</p>" +
      "</section>";
  }

  /** Where the dates come from, said once under them. */
  function datesNote(all, info) {
    if (!info || !info.lines.length) return "";
    var d = all._dates || {};
    // Not every date is printed as a date: where the office or its law
    // gives a rule ("15 days before the election", Guam's runoff "on the
    // fourteenth day" after it), the date is that rule counted on the 2026
    // calendar, and the page says so (PR #102 review).
    return "Each date is from the election office's own page or the law, linked beside it" +
      (d.read ? ", read on " + KYC.escapeHtml(d.read) : "") +
      (d.checked ? " and checked again on " + KYC.escapeHtml(d.checked) : "") +
      "; where the source gives a rule, such as “15 days before the election”, the date " +
      "is that rule counted on the 2026 calendar. Whether a date has passed is counted on your " +
      "device's calendar. ";
  }

  /* A non-voting member's title, as summary.py gives it: Puerto Rico's
   * Resident Commissioner is not a "delegate". */
  function delegateTitle(info) {
    return info.delegateTitle || "Delegate";
  }

  /* Who holds the state's seats, in words: the hero and the directory of
   * states say it the same way. */
  function seatWords(info) {
    var seats = [];
    if (info.senators) seats.push(plural(info.senators, "senator"));
    if (info.house) seats.push(plural(info.house, "representative"));
    if (info.delegates) {
      var title = delegateTitle(info);
      seats.push(plural(info.delegates, title === "Delegate" ? "delegate" : title));
    }
    return seats;
  }

  /* A House seat elected for longer than two years and not on this
   * cycle's ballot (Puerto Rico's): why it has no race, in place of the
   * zeros. */
  function offCycle(info) {
    var term = info.houseTerm;
    if (!term || info.races) return "";
    return delegateTitle(info) + ": a " + term.years + "-year term, next on the ballot in " + term.next;
  }

  function summaryStrip(info) {
    var parts = seatWords(info);
    if (offCycle(info)) {
      parts.push(offCycle(info));
      return badges(parts);
    }
    // Once the new Congress sits these are a record of 2026, and say so.
    var rec = KYC.recordPhase();
    parts.push(plural(info.seatsUp, "seat") + " in Congress on the 2026 ballot");
    if (info.open) parts.push(plural(info.open, "open seat") + (rec ? " in 2026" : ""));
    if (info.renumbered) {
      parts.push(plural(info.renumbered, "member") + " running under a new district number");
    }
    parts = parts.concat(runningWords(info, rec));
    if (info.challengersOut) {
      parts.push(plural(info.challengersOut, "candidate") + " out after the " +
        (rec ? "2026 " : "") + "primaries");
    }
    return badges(parts);
  }

  /** Who is on the ballot besides members running for their own seats, in
   *  the race headers' words: "challengers" where someone holds the seat on
   *  the ballot, "candidates" for an open seat, where nobody is challenging
   *  anyone. Wyoming's two open seats read "4 challengers" over two race
   *  heads that said "candidates" (audit 2026-10-17, RACES-14). The two
   *  figures sum to the race headers' total (summary.by_state, rule 73). */
  function runningWords(info, rec) {
    var where = rec ? " on the 2026 ballot" : " on the ballot";
    var open = info.openCandidates || 0;
    var held = (info.challengersOnBallot || 0) - open;
    var out = [];
    if ((held || !open) && (held || !info.challengersFiled)) out.push(plural(held, "challenger") + where);
    if (open) out.push(plural(open, "candidate") + " for open seats" + where);
    // Where there is no primary and no ballot list was read (a territory
    // whose list this site has no reader for): filed, which is not the same
    // claim, and says what was not done - it checked no list, which is not
    // to say none is published (rule 19). American Samoa read "0
    // challengers on the ballot" over six filers.
    if (info.challengersFiled) {
      out.push(plural(info.challengersFiled, "challenger") + " filed; ballot list not checked");
    }
    return out;
  }

  function badges(parts) {
    return parts.map(function (t) {
      return '<span class="badge badge-neutral">' + KYC.escapeHtml(t) + "</span>";
    }).join(" ");
  }

  /* The delegation by party. *vacant* is the state's empty seats, which
   * have no profile to count (summary.py counts them from the races), so
   * the heading agrees with the sidebar. */
  function balance(people, vacant) {
    var counts = { vacant: vacant || 0 };
    people.forEach(function (p) {
      var key = KYC.partyKey(p);
      counts[key] = (counts[key] || 0) + 1;
    });
    var order = [["r", "R"], ["d", "D"], ["i", "I"], ["vacant", "Vacant"]];
    return order.filter(function (o) { return counts[o[0]]; }).map(function (o) {
      return '<span class="party-' + o[0] + '">' + counts[o[0]] + " " + o[1] + "</span>";
    }).join('<span class="sep">/</span>');
  }

  /* The government section's name, for its heading and its jump chip
   * alike: D.C.'s is a local government, a territory's territorial. */
  function govHeading(info) {
    return code === "DC" ? "Local government" : info.territory ? "Territorial government" : "State government";
  }

  function renderState() {
    var target = el("stateContent");
    var info = (KYC.meta().states || {})[code];
    if (!info) {
      target.innerHTML = '<div class="empty-state"><h3>No such state</h3>' +
        "<p>Nothing in the data is filed under " + KYC.escapeHtml(code) + ".</p></div>";
      return;
    }
    var name = info.name;
    // The guide's page on state government, by the name it gives itself
    // (pages._state_main): never retyped here (rule 75).
    var guideName = target.getAttribute("data-guide-name") || "";
    doc.title = name + " — Know Your Candidate";
    // Every state links to its district map; a redrawn one says so.
    var districtMap = (KYC.meta().districtMaps || {})[code];

    // Who represents the state now (rule 27): never a former member.
    var members = data.filter(function (p) { return KYC.seated(p) && p.state === code; });
    var senators = members.filter(function (p) { return p.chamber.indexOf("Senate") !== -1; });
    var house = members.filter(function (p) { return p.chamber.indexOf("House") !== -1; })
      .sort(function (a, b) { return KYC.districtOrder(a) - KYC.districtOrder(b); });

    var stateRaces = races.filter(function (r) { return r.state === code; });
    var senateRaces = stateRaces.filter(function (r) { return r.chamber === "Senate"; });
    var houseRaces = stateRaces.filter(function (r) { return r.chamber === "House"; })
      .sort(function (a, b) { return (a.district || 0) - (b.district || 0); });

    var html = [];
    html.push(
      '<header class="state-hero">',
      '<p class="state-kicker">State &amp; territory pages</p>',
      '<h1 class="state-title">' + KYC.escapeHtml(name) + "</h1>",
      '<p class="state-summary">' + summaryStrip(info) + "</p>",
      '<p class="state-links">',
      '<a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "map.html#/?state=" + code) + '">' +
        KYC.icon("map") + " See on the map</a> ",
      '<a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "index.html#/?state=" + code) + '">' +
        KYC.icon("grid") + " All " + KYC.escapeHtml(name) + " profiles</a>",
      districtMap
        ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + districtMap.page) + '">' +
          KYC.icon("layers") + (districtMap.redrawn ? " Old and new district lines" :
            " District map") + "</a>"
        : "",
      // Every state - not D.C. or a territory - has a legislature page.
      info.senators
        ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "legislature/" +
          code.toLowerCase() + ".html") + '">' + KYC.icon("landmark") + " State legislature</a>" +
          ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "counties/" +
          code.toLowerCase() + ".html") + '">' + KYC.icon("layers") + " Counties &amp; local governments</a>" +
          (guideName ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "government/states.html") +
            '">' + KYC.icon("scroll") + " " + KYC.escapeHtml(guideName) + "</a>" : "")
        : "",
      "</p>",
      "</header>"
    );
    /* Where each part of the page starts. On a phone Texas's House
     * delegation alone is 6,500px of cards, and the 2026 races began eleven
     * screens down with the only way to them inside the closed drawer. */
    var parts = [
      senators.length ? ["senators", "U.S. senators"] : null,
      house.length ? ["delegation", info.territory ? delegateTitle(info) : "House delegation"] : null,
      KYC.stategov && (KYC.stategov.state(code) || code === "DC") ? ["state-government", govHeading(info)] : null,
      senateRaces.length + houseRaces.length ? ["races", "2026 races"] : null,
    ].filter(Boolean);
    if (parts.length > 1) {
      html.push('<nav class="toolbar jump-row state-parts" aria-label="On this page">' +
        parts.map(function (p) {
          return '<a class="chip chip-link" href="#' + p[0] + '">' + KYC.escapeHtml(p[1]) + "</a>";
        }).join("") + "</nav>");
    }

    html.push(votingBlock(code, name));

    /* Who holds the seats now. Senators first, then the House by district;
     * a reader who asked "who represents me" gets the answer before the
     * page turns to who is running (rule 27). */
    if (senators.length) {
      html.push(
        '<section class="state-section" id="senators">',
        '<h2 class="state-heading">U.S. senators <span class="balance">' + balance(senators) + "</span></h2>",
        '<div class="card-grid">' + senators.map(cards.card).join("") + "</div>",
        "</section>"
      );
    }
    if (house.length) {
      html.push(
        '<section class="state-section" id="delegation">',
        '<h2 class="state-heading">' + (info.territory ? KYC.escapeHtml(delegateTitle(info)) +
          " to the U.S. House" : "U.S. House delegation") +
          ' <span class="balance">' + balance(house,
            ((info.balance || {}).house || {}).vacant) + "</span></h2>",
        offCycle(info)
          ? '<p class="state-note">' + KYC.escapeHtml(name) + " elects its " +
            KYC.escapeHtml(delegateTitle(info)) + " at large for a " + info.houseTerm.years +
            '-year term (<a href="https://www.law.cornell.edu/uscode/text/48/891" target="_blank" ' +
            'rel="noopener noreferrer">48 U.S.C. § 891</a>). The seat was last on the ballot in ' +
            info.houseTerm.last + " and is next in " + info.houseTerm.next + ", so no seat in Congress " +
            "is on " + KYC.escapeHtml(KYC.possessive(name)) + " 2026 ballot.</p>"
          : "",
        // Each empty seat: who left, when, and whether a special election
        // has been called (summary.py, overrides.SEAT_VACANCIES).
        (info.vacancies || []).map(function (v) {
          return '<p class="state-note">District ' + v.district + ": " +
            KYC.escapeHtml(KYC.vacancyNote(v)) + "</p>";
        }).join(""),
        '<div class="card-grid">' + house.map(cards.card).join("") + "</div>",
        "</section>"
      );
    }

    /* Who runs the state itself: drawn by the module the map's state views
     * use, so the two say the same thing. */
    if (KYC.stategov && (KYC.stategov.state(code) || code === "DC")) {
      html.push(
        '<section class="state-section" id="state-government">',
        '<h2 class="state-heading">' + govHeading(info) + "</h2>",
        '<div class="stategov">' + KYC.stategov.render(code, { links: false }) + "</div>",
        "</section>"
      );
    }

    /* The 2026 races, one section each, in ballot order. */
    var raceHtml = senateRaces.concat(houseRaces).map(function (race) {
      var people = peopleIn(race);
      return cards.raceSection(race, people, { title: districtLabel(race), stateLink: false,
                                               fullOdds: true });
    }).join("");
    if (raceHtml) {
      /* Texas has 38 districts; a row of jump chips saves the scroll. */
      var jumps = senateRaces.concat(houseRaces).map(function (race) {
        var short = race.chamber === "Senate" ? "Senate" : (race.district ? String(race.district) : "At-large");
        return '<a class="chip chip-link" href="#' + KYC.escapeAttr("race-" + race.id) + '" title="' +
          KYC.escapeAttr(districtLabel(race)) + '">' + KYC.escapeHtml(short) + "</a>";
      }).join("");
      html.push(
        '<section class="state-section" id="races">',
        // Congress only, and it says so: a list that looked like the whole
        // ballot left out the governor, the legislature and every local race.
        '<h2 class="state-heading">2026 races for Congress in ' + KYC.escapeHtml(name) + "</h2>",
        '<p class="state-note">Each seat with the sitting member, everyone on the ' +
          "November ballot, and - folded under the race - everyone no longer running. " +
          alsoOnBallot(code, name, info.territory) + "</p>",
        (senateRaces.length + houseRaces.length > 3
          ? '<nav class="toolbar jump-row" aria-label="Jump to a race">' + jumps + "</nav>"
          : ""),
        raceHtml,
        "</section>"
      );
    }

    target.innerHTML = html.join("");
  }

  /** What else the state's November 3 ballot elects, from the same table the
   *  State government section marks, in a sentence. This site lists the
   *  candidates for Congress only, and says so. */
  function alsoOnBallot(code, name, territory) {
    var list = KYC.stategov ? KYC.stategov.ballotList(code) : null;
    var rest = "special elections for vacant seats, other statewide, judicial and local " +
      "contests, and ballot measures, which this site does not list";
    if (code === "DC") {
      // D.C. has no governor or legislature; its own offices, as the D.C.
      // Board of Elections lists them for 2026 (candidate list, July 2026).
      return "Your ballot may also hold the District's own contests, such as for mayor, attorney " +
        "general, the D.C. Council, the State Board of Education and Advisory Neighborhood " +
        "Commissions, which this site does not list (" +
        '<a href="https://www.dcboe.org/elections/2026-elections" target="_blank" ' +
        'rel="noopener noreferrer">D.C. Board of Elections</a>).';
    }
    if (territory) {
      // A territory's own record covers its governor only (ballot2026.TERRITORIES):
      // its legislature and local offices are not in it, and are said so.
      return (list
        ? "Of the territorial offices this site covers, the same ballot also elects the " +
          KYC.escapeHtml(list.replace(/^the /, "")) + " (see " +
          '<a class="state-jump" href="#state-government">Territorial government</a>). '
        : list === "" ? KYC.escapeHtml(name) + " does not elect its governor in 2026. " : "") +
        "Your ballot may also hold territorial and local contests, such as for the " +
        "legislature, which this site does not list.";
    }
    if (list === null) {
      return "Your ballot may also hold local contests, which this site does not list.";
    }
    if (!list) {
      return "None of " + KYC.escapeHtml(KYC.possessive(name)) + " governor, lieutenant governor, attorney " +
        "general, secretary of state or regular legislative seats is elected in 2026; the " +
        "ballot may still hold " + rest + ".";
    }
    return "Of the state offices this site covers, the same ballot also elects " +
      KYC.escapeHtml(list) + " (see " +
      '<a class="state-jump" href="#state-government">State government</a>). It may also hold ' +
      rest + ". This site lists the candidates for Congress only.";
  }

  /* A link to a section of this page ("#state-government", from the guide)
   * arrives before the script has drawn that section, so the browser's own
   * jump finds nothing. Jump once it is there, then drop the fragment: left
   * in the address, closing a profile returned to it and jumped the reader
   * back to the section, however far they had read on. */
  function jumpToSection() {
    var hash = global.location.hash;
    if (!/^#[A-Za-z][\w-]*$/.test(hash)) return;
    var section = doc.getElementById(hash.slice(1));
    if (!section) return;
    if (section.scrollIntoView) section.scrollIntoView({ block: "start" });
    if (global.history && global.history.replaceState) {
      global.history.replaceState(global.history.state, "", global.location.pathname + global.location.search);
    }
  }

  /* ---------------------------------------------------------- all states */

  function renderIndex() {
    var target = el("stateContent");
    var states = KYC.meta().states || {};
    var codes = Object.keys(states).sort(function (a, b) {
      return states[a].name.localeCompare(states[b].name);
    });
    doc.title = "States & territories — Know Your Candidate";

    var rows = codes.map(function (c) {
      var info = states[c];
      var seats = seatWords(info);
      var off = offCycle(info);
      return [
        '<a class="state-row" href="' + KYC.escapeAttr(KYC.stateUrl(c)) + '" data-state="' + KYC.escapeAttr(c) + '">',
        '<span class="state-row-name">' + KYC.escapeHtml(info.name) +
          ' <span class="state-row-code">' + KYC.escapeHtml(c) + "</span></span>",
        '<span class="state-row-meta">' + KYC.escapeHtml(seats.join(", ")) + "</span>",
        off
          ? '<span class="state-row-meta">' + KYC.escapeHtml(off) + '</span><span class="state-row-meta"></span>'
          : '<span class="state-row-meta">' + KYC.escapeHtml(plural(info.seatsUp, "seat") +
            (KYC.recordPhase() ? " on the 2026 ballot" : " up")) +
            (info.open ? " &middot; " + KYC.escapeHtml(plural(info.open, "open seat")) : "") + "</span>" +
            '<span class="state-row-meta">' +
            KYC.escapeHtml(runningWords(info, KYC.recordPhase()).join(" · ")) + "</span>",
        "</a>",
      ].join("");
    });

    target.innerHTML = [
      '<header class="state-hero">',
      '<h1 class="state-title">States &amp; territories</h1>',
      '<p class="state-summary">One page each: who holds the seats, the 2026 races, and everyone who has filed.</p>',
      "</header>",
      '<div class="state-list" id="stateList">' + rows.join("") + "</div>",
    ].join("");
  }

  /* --------------------------------------------------------------- chrome */

  function initSearch() {
    var input = el("stateSearch");
    if (!input) return;
    var run = KYC.debounce(function () {
      var q = input.value.trim().toLowerCase();
      if (kind === "states") {
        // Folded like every other search on the site (KYC.foldText).
        var folded = KYC.foldText(q);
        Array.prototype.forEach.call(doc.querySelectorAll(".state-row"), function (row) {
          row.hidden = !!folded && KYC.foldText(row.textContent).indexOf(folded) === -1;
        });
        return;
      }
      Array.prototype.forEach.call(doc.querySelectorAll("#stateContent .card"), function (c) {
        var item = KYC.byId(c.getAttribute("data-id"));
        c.hidden = !!q && !(item && KYC.matchesQuery(item, q));
      });
    }, 120);
    input.addEventListener("input", run);
  }

  function initCards() {
    el("stateContent").addEventListener("click", function (event) {
      // A jump within the page scrolls there and leaves the address alone.
      // A fragment left in it sent the reader back to that section when a
      // profile closed, however far they had read on (as jumpToSection says).
      var jump = event.target.closest('.jump-row a[href^="#"], a.state-jump[href^="#"]');
      if (jump) {
        var target = doc.getElementById(jump.getAttribute("href").slice(1));
        if (target) {
          event.preventDefault();
          if (target.scrollIntoView) target.scrollIntoView({ block: "start" });
          if (target.focus) {
            if (!target.hasAttribute("tabindex")) target.setAttribute("tabindex", "-1");
            target.focus({ preventScroll: true });
          }
        }
        return;
      }
      var card = event.target.closest("[data-id]");
      if (card) KYC.profile.open(card.getAttribute("data-id"));
    });
  }

  function applyRoute(route) {
    if (route.view === "profile" && KYC.profile.open(route.id, { fromRoute: true })) return;
    if (KYC.profile.isOpen()) KYC.profile.close();
  }

  KYC.ready(function () {
    if (!data.length) {
      el("stateContent").innerHTML =
        '<p class="results-bar">Profile data did not load. Run: python build_profile_site.py</p>';
      return;
    }
    KYC.profile.ensure();
    if (kind === "states") renderIndex(); else { renderState(); jumpToSection(); }
    initSearch();
    initCards();
    KYC.router.onChange(function () { applyRoute(KYC.router.read()); });
    applyRoute(KYC.router.read());
  });
})(window);
